public class MaxDifferenceOptimized {

    public static int[] findMaxDifferenceOptimized(int[] list) {
        int minElement = list[0];
        int maxElement = list[0];
        int minIndex = 0;
        int maxIndex = 0;

        for (int i = 1; i < list.length; i++) {
            if (list[i] < minElement) {
                minElement = list[i];
                minIndex = i;
