public class CopyOnWriteBenchmark {

    @State(Scope.Thread)
    public static class MyState {

        CopyOnWriteArrayList<Employee> employeeList = new CopyOnWriteArrayList<>();

        long iterations = 100000;

        Employee employee = new Employee(100L, "Harry");

        int employeeIndex = -1;

        @Setup(Level.Trial)
